SELECT p.id, p.title, p.difficulty, p.accepted_user_count, p.last_synced_at, t.name AS tag_name FROM problems p LEFT JOIN problem_tags pt ON p.id = pt.problem_id LEFT JOIN tags t ON pt.tag_id = t.id WHERE p.id IN
#{id}
ORDER BY p.id

SELECT p.id, p.title, p.difficulty, p.accepted_user_count, p.last_synced_at, t.name AS tag_name FROM problems p LEFT JOIN problem_tags pt ON pt.problem_id = p.id LEFT JOIN tags t ON t.id = pt.tag_id WHERE 1 = 1
AND p.difficulty >= #{difficultyFrom}
AND p.difficulty <= #{difficultyTo}
AND p.accepted_user_count >= #{minSolvers}
AND EXISTS ( SELECT 1 FROM problem_tags pt2 JOIN tags t2 ON t2.id = pt2.tag_id WHERE pt2.problem_id = p.id AND t2.name IN
#{tag}
)
ORDER BY p.id

SELECT p.id, p.title, p.difficulty, p.accepted_user_count, p.last_synced_at, t.name AS tag_name FROM problems p LEFT JOIN problem_tags pt ON pt.problem_id = p.id LEFT JOIN tags t ON t.id = pt.tag_id WHERE NOT EXISTS( SELECT 1 FROM user_groups ug JOIN user_solutions us ON us.user_id = ug.user_id AND us.problem_id = p.id WHERE ug.group_id = #{groupId} AND ug.status = 'ACTIVE' )
AND p.difficulty >= #{difficultyFrom}
AND p.difficulty <= #{difficultyTo}
AND p.accepted_user_count >= #{minSolvers}
AND EXISTS ( SELECT 1 FROM problem_tags pt2 JOIN tags t2 ON t2.id = pt2.tag_id WHERE pt2.problem_id = p.id AND t2.name IN
#{tag}
)
ORDER BY p.id
